package com.b5.shared;import org.junit.Test;import static org.junit.Assert.*;public class PolicyTest {@Test public void durations(){assertEquals(3600000L,Policy.duration("1H"));assertEquals(30*Policy.DAY,Policy.duration("30D"));assertEquals(0,Policy.duration("LIFETIME"));}@Test public void expiryBoundary(){assertTrue(Policy.expired(1000,1000));assertFalse(Policy.expired(0,999999));assertFalse(Policy.expired(1001,1000));}@Test public void extensionPreservesRemaining(){assertEquals(2000+7*Policy.DAY,Policy.extended(2000,1000));assertEquals(3000+7*Policy.DAY,Policy.extended(2000,3000));}@Test public void codeFormat(){assertTrue(Policy.validCode("USA-A0Z9"));assertFalse(Policy.validCode("USA-A/B1"));assertFalse(Policy.validCode("usa-aaaa"));}@Test public void countdown(){assertEquals("1 Days 01 Hours 01 Min 01 Sec",Policy.remaining(90061000,0));assertEquals("0 Days 00 Hours 00 Min 00 Sec",Policy.remaining(1,10));}}